CREATE TABLE "journal_entries" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "job_id" character varying NOT NULL, "device_id" character varying NULL, "attempt" bigint NOT NULL, "node_id" character varying NOT NULL, "run_id" character varying NOT NULL, "sequence" bigint NOT NULL, "dag_id" character varying NULL, "dag_version" character varying NULL, "fqcn" character varying NULL, "fqcn_unresolved" boolean NOT NULL DEFAULT false, "task_name" character varying NULL, "register" character varying NULL, "started_at" timestamptz NULL, "finished_at" timestamptz NULL, "outcome" character varying NOT NULL, "failure_stage" character varying NULL, "skip_kind" character varying NULL, "skip_ordinal" bigint NOT NULL DEFAULT 0, "skip_total" bigint NOT NULL DEFAULT 0, "stat_keys" jsonb NULL, "undeclared_stat_count" bigint NOT NULL DEFAULT 0, "param_keys" jsonb NULL, "undeclared_param_count" bigint NOT NULL DEFAULT 0, "inverse_fqcn" character varying NULL, "inverse_fqcn_unresolved" boolean NOT NULL DEFAULT false, "inverse_param_keys" jsonb NULL, "undeclared_inverse_param_count" bigint NOT NULL DEFAULT 0, "diff_recorded" boolean NOT NULL DEFAULT false, PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "journalentry_job_id_device_id_attempt_node_id" ON "journal_entries" ("job_id", "device_id", "attempt", "node_id");
CREATE INDEX "journalentry_job_id_device_id_attempt_sequence" ON "journal_entries" ("job_id", "device_id", "attempt", "sequence");
